async () => {
            const deadline = Date.now() + 180000;
            while (Date.now() < deadline) {
              const ready = document.querySelectorAll('[data-model-loader-state="ready"]').length;
              if (ready >= 2) return { ready };
              await new Promise(resolve => setTimeout(resolve, 500));
            }
            throw new Error('MobileViT loader did not reach ready');
          }
